import{_ as t,o as a,c as d,ao as o}from"./chunks/framework.CvgPK7Hc.js";const h=JSON.parse('{"title":"File formats","description":"","frontmatter":{},"headers":[],"relativePath":"formats.md","filePath":"formats.md","lastUpdated":null}'),l={name:"formats.md"};function i(r,e,s,n,c,p){return a(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="File-formats" tabindex="-1">File formats <a class="header-anchor" href="#File-formats" aria-label="Permalink to &quot;File formats {#File-formats}&quot;">​</a></h1><p>The picker recognises its files by their content, not by their extension.</p><h2 id="Profiles-.pgmg" tabindex="-1">Profiles (<code>.pgmg</code>) <a class="header-anchor" href="#Profiles-.pgmg" aria-label="Permalink to &quot;Profiles (`.pgmg`) {#Profiles-.pgmg}&quot;">​</a></h2><p>A JLD2 file with a single entry, a GeophysicalModelGenerator <code>ProfileData</code> object. The name of the entry does not matter. Profile files are made with GeophysicalModelGenerator.jl (branch <code>profile_processing_mt</code>); see <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/internals#AdriaArrayGeometryPicker.load_profile!"><code>load_profile!</code></a>.</p><p>The picker uses these fields of the <code>ProfileData</code>:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Used for</th></tr></thead><tbody><tr><td style="text-align:left;"><code>vertical</code></td><td style="text-align:left;">vertical cross-section (<code>true</code>) or horizontal slice (<code>false</code>)</td></tr><tr><td style="text-align:left;"><code>start_lonlat</code>, <code>end_lonlat</code></td><td style="text-align:left;">start and end point of a vertical profile</td></tr><tr><td style="text-align:left;"><code>depth</code></td><td style="text-align:left;">depth of a horizontal slice</td></tr><tr><td style="text-align:left;"><code>VolData</code></td><td style="text-align:left;">volume data (a <code>GeoData</code>, or a <code>NamedTuple</code> of them), shown as heatmap and contour lines</td></tr><tr><td style="text-align:left;"><code>SurfData</code></td><td style="text-align:left;">surface data (<code>NamedTuple</code> of <code>GeoData</code>), shown as lines</td></tr><tr><td style="text-align:left;"><code>PointData</code></td><td style="text-align:left;">point data (<code>NamedTuple</code> of <code>GeoData</code>), shown as markers</td></tr><tr><td style="text-align:left;"><code>TopoData</code></td><td style="text-align:left;">topography (<code>NamedTuple</code> of <code>GeoData</code>)</td></tr></tbody></table><h2 id="Picks-.aagpp,-.csv" tabindex="-1">Picks (<code>.aagpp</code>, <code>.csv</code>) <a class="header-anchor" href="#Picks-.aagpp,-.csv" aria-label="Permalink to &quot;Picks (`.aagpp`, `.csv`) {#Picks-.aagpp,-.csv}&quot;">​</a></h2><p>Written by <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.save_picks"><code>save_picks</code></a> (<strong>Menu → Save Picks</strong>), read by <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.load_picks"><code>load_picks</code></a>.</p><h3 id="JLD2-.aagpp" tabindex="-1">JLD2 (<code>.aagpp</code>) <a class="header-anchor" href="#JLD2-.aagpp" aria-label="Permalink to &quot;JLD2 (`.aagpp`) {#JLD2-.aagpp}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Entry</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>format</code></td><td style="text-align:left;"><code>&quot;AdriaArrayGeometryPicker.Picks&quot;</code></td></tr><tr><td style="text-align:left;"><code>version</code></td><td style="text-align:left;"><code>1</code></td></tr><tr><td style="text-align:left;"><code>names</code></td><td style="text-align:left;">the names of the two coordinates, e.g. <code>[&quot;x&quot;, &quot;depth&quot;]</code></td></tr><tr><td style="text-align:left;"><code>picks</code></td><td style="text-align:left;">all columns as a <code>NamedTuple</code> of vectors, e.g. <code>(x = [...], depth = [...], lon = [...], lat = [...])</code></td></tr><tr><td style="text-align:left;"><code>metadata</code></td><td style="text-align:left;">a <code>Dict{String,Any}</code></td></tr></tbody></table><h3 id="CSV-.csv" tabindex="-1">CSV (<code>.csv</code>) <a class="header-anchor" href="#CSV-.csv" aria-label="Permalink to &quot;CSV (`.csv`) {#CSV-.csv}&quot;">​</a></h3><p>Metadata as <code># key = value</code> comment lines (nested keys joined with <code>.</code>), then a header row and one row per pick:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># AdriaArrayGeometryPicker.Picks v1</span></span>\n<span class="line"><span># date = 2026-10-05T10:31:12.123</span></span>\n<span class="line"><span># end_lonlat = (15.465423125301268, 47.79656290565586)</span></span>\n<span class="line"><span># profile_file = Profile1.pgmg</span></span>\n<span class="line"><span># profile_type = vertical</span></span>\n<span class="line"><span># start_lonlat = (9.777223439354351, 42.936916884179524)</span></span>\n<span class="line"><span># user = MT</span></span>\n<span class="line"><span>x,depth,lon,lat</span></span>\n<span class="line"><span>60.0,-35.0,10.257199224941168,43.346978510988194</span></span>\n<span class="line"><span>180.0,-45.0,11.221291268553239,44.17063912818688</span></span></code></pre></div><p>Metadata values in CSV files are text, so they come back as strings from <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.load_picks"><code>load_picks</code></a>.</p><h3 id="Columns-and-metadata-of-picks-made-in-the-picker" tabindex="-1">Columns and metadata of picks made in the picker <a class="header-anchor" href="#Columns-and-metadata-of-picks-made-in-the-picker" aria-label="Permalink to &quot;Columns and metadata of picks made in the picker {#Columns-and-metadata-of-picks-made-in-the-picker}&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Column</th><th style="text-align:left;">Vertical profile</th><th style="text-align:left;">Horizontal slice</th></tr></thead><tbody><tr><td style="text-align:left;"><code>x</code></td><td style="text-align:left;">distance along the profile (km)</td><td style="text-align:left;"><code>NaN</code></td></tr><tr><td style="text-align:left;"><code>depth</code></td><td style="text-align:left;">depth (km)</td><td style="text-align:left;">depth of the slice</td></tr><tr><td style="text-align:left;"><code>lon</code>, <code>lat</code></td><td style="text-align:left;">interpolated along the profile (<code>NaN</code> outside the profile)</td><td style="text-align:left;">picked position</td></tr></tbody></table><table tabindex="0"><thead><tr><th style="text-align:left;">Metadata</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>user</code></td><td style="text-align:left;">the name in the <strong>User name</strong> field</td></tr><tr><td style="text-align:left;"><code>date</code></td><td style="text-align:left;">date and time of saving</td></tr><tr><td style="text-align:left;"><code>profile_file</code></td><td style="text-align:left;">file name of the profile</td></tr><tr><td style="text-align:left;"><code>profile_type</code></td><td style="text-align:left;"><code>&quot;vertical&quot;</code> or <code>&quot;horizontal&quot;</code></td></tr><tr><td style="text-align:left;"><code>start_lonlat</code>, <code>end_lonlat</code></td><td style="text-align:left;">start and end of a vertical profile</td></tr><tr><td style="text-align:left;"><code>depth</code></td><td style="text-align:left;">depth of a horizontal slice</td></tr></tbody></table><h3 id="Older-pick-files" tabindex="-1">Older pick files <a class="header-anchor" href="#Older-pick-files" aria-label="Permalink to &quot;Older pick files {#Older-pick-files}&quot;">​</a></h3><p><a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.load_picks"><code>load_picks</code></a> also reads the pick files of MakiePickerGUI.jl (format <code>&quot;MakiePickerGUI.Picks&quot;</code>) and of the original AdriaArrayGeometryPicker.jl (<code>.jld2</code>).</p><h2 id="State-of-the-window-.aagps" tabindex="-1">State of the window (<code>.aagps</code>) <a class="header-anchor" href="#State-of-the-window-.aagps" aria-label="Permalink to &quot;State of the window (`.aagps`) {#State-of-the-window-.aagps}&quot;">​</a></h2><p>Written by <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.save_gui_state"><code>save_gui_state</code></a> (<strong>Menu → Save State</strong>), read by <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/public#AdriaArrayGeometryPicker.load_gui_state!"><code>load_gui_state!</code></a>. A JLD2 file with:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Entry</th><th style="text-align:left;">Content</th></tr></thead><tbody><tr><td style="text-align:left;"><code>format</code></td><td style="text-align:left;"><code>&quot;AdriaArrayGeometryPicker state&quot;</code> (state files of MakiePickerGUI.jl: <code>&quot;MakiePickerGUI state&quot;</code>)</td></tr><tr><td style="text-align:left;"><code>version</code></td><td style="text-align:left;"><code>1</code></td></tr><tr><td style="text-align:left;"><code>profile_path</code></td><td style="text-align:left;">full path of the profile file; the profile is loaded again from this file</td></tr><tr><td style="text-align:left;"><code>settings</code></td><td style="text-align:left;">a <code>Dict{String,Any}</code> with the settings of the window, see <a href="/AdriaArrayGeometryPicker.jl/previews/PR19/api/internals#AdriaArrayGeometryPicker.gui_settings"><code>gui_settings</code></a></td></tr></tbody></table>',22)])])}const y=t(l,[["render",i]]);export{h as __pageData,y as default};
